COMMITMENT_COLS = [
    "id", "developer_id", "date_made", "venue", "category", "commitment_text", "kept_would_look_like",
    "source_url", "status", "evidence_url", "last_reviewed", "reviewer", "notes",
]
INCIDENT_COLS = [
    "id", "date", "developer_id", "system", "description", "severity", "source_url", "source_type",
    "developer_acknowledged", "status", "last_reviewed", "reviewer", "notes",
]
COMMITMENT_STATUS = {"kept", "partially_kept", "not_kept", "superseded", "in_progress", "unverifiable", "needs_verification"}
INCIDENT_STATUS = {"reported", "acknowledged", "disputed", "resolved", "needs_verification"}
SEVERITY = {"low", "medium", "high", "unknown"}
ACK = {"yes", "no", "partial", "unknown"}
SOURCE_TYPE = {"developer", "government", "court", "press", "research", "other"}
URL_RE = re.compile(r"^https?://[^\s]+$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def read(path):
    with open(path, newline="", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
        f.seek(0)
        header = next(csv.reader(f))
    return header, rows


def check_date(value, label, errors, required=True):
    if not value:
        if required:
            errors.append(f"{label}: missing date")
        return
    if not DATE_RE.match(value):
        errors.append(f"{label}: bad date format {value!r} (want YYYY-MM-DD)")
        return
    try:
        if date.fromisoformat(value) > date.today():
            errors.append(f"{label}: date {value} is in the future")
    except ValueError:
        errors.append(f"{label}: invalid date {value!r}")


def validate_commitments(developers, errors):
    header, rows = read(HERE / "commitments.csv")
    if header != COMMITMENT_COLS:
        errors.append(f"commitments.csv: header mismatch\n  got  {header}\n  want {COMMITMENT_COLS}")
        return
    seen = set()
    for i, r in enumerate(rows, start=2):
        label = f"commitments.csv:{i} ({r['id']})"
        if not re.match(r"^C-\d{4}$", r["id"]):
            errors.append(f"{label}: id must look like C-0001")
        if r["id"] in seen:
            errors.append(f"{label}: duplicate id")
        seen.add(r["id"])
        if r["developer_id"] not in developers:
            errors.append(f"{label}: unknown developer_id {r['developer_id']!r}")
        check_date(r["date_made"], label + " date_made", errors)
        check_date(r["last_reviewed"], label + " last_reviewed", errors, required=False)
        if not r["commitment_text"].strip():
            errors.append(f"{label}: empty commitment_text")
        if not URL_RE.match(r["source_url"]):
            errors.append(f"{label}: source_url is not a URL")
        if r["evidence_url"] and not URL_RE.match(r["evidence_url"]):
            errors.append(f"{label}: evidence_url is not a URL")
        if r["status"] not in COMMITMENT_STATUS:
            errors.append(f"{label}: bad status {r['status']!r}")
        if r["status"] != "needs_verification" and not (r["last_reviewed"] and r["reviewer"]):
            errors.append(f"{label}: status {r['status']} requires last_reviewed and reviewer")
        if r["status"] in {"kept", "partially_kept", "not_kept"} and not r["evidence_url"]:
            errors.append(f"{label}: status {r['status']} requires evidence_url")
        if r["status"] != "unverifiable" and not r["kept_would_look_like"].strip():
            errors.append(f"{label}: kept_would_look_like is empty")
    return len(rows)


def validate_incidents(developers, errors):
    header, rows = read(HERE / "incidents.csv")
    if header != INCIDENT_COLS:
        errors.append(f"incidents.csv: header mismatch\n  got  {header}\n  want {INCIDENT_COLS}")
        return
    seen = set()
    for i, r in enumerate(rows, start=2):
        label = f"incidents.csv:{i} ({r['id']})"
        if not re.match(r"^I-\d{4}$", r["id"]):
            errors.append(f"{label}: id must look like I-0001")
        if r["id"] in seen:
            errors.append(f"{label}: duplicate id")
        seen.add(r["id"])
        if r["developer_id"] not in developers:
            errors.append(f"{label}: unknown developer_id {r['developer_id']!r}")
        check_date(r["date"], label + " date", errors)
        check_date(r["last_reviewed"], label + " last_reviewed", errors, required=False)
        if not r["description"].strip():
            errors.append(f"{label}: empty description")
        if r["severity"] not in SEVERITY:
            errors.append(f"{label}: bad severity {r['severity']!r}")
        if not URL_RE.match(r["source_url"]):
            errors.append(f"{label}: source_url is not a URL")
        if r["source_type"] not in SOURCE_TYPE:
            errors.append(f"{label}: bad source_type {r['source_type']!r}")
        if r["developer_acknowledged"] not in ACK:
            errors.append(f"{label}: developer_acknowledged must be one of {sorted(ACK)}")
        if r["status"] not in INCIDENT_STATUS:
            errors.append(f"{label}: bad status {r['status']!r}")
        if r["status"] != "needs_verification" and not (r["last_reviewed"] and r["reviewer"]):
            errors.append(f"{label}: status {r['status']} requires last_reviewed and reviewer")
    return len(rows)


def main():
    errors = []
    _, dev_rows = read(HERE / "developers.csv")
    developers = {r["developer_id"] for r in dev_rows}
    n_c = validate_commitments(developers, errors)
    n_i = validate_incidents(developers, errors)
    if errors:
        print("\n".join(errors))
        print(f"\n{len(errors)} problem(s).")
        sys.exit(1)
    print(f"OK — {n_c} commitments, {n_i} incidents, {len(developers)} developers.")


if __name__ == "__main__":
    main()
